186	async function loadFleet() {
187	  const fleet = await getJSON("/api/fleet");
188	  const tbody = document.getElementById("fleet-tbody");
189	  tbody.innerHTML = "";
190	  fleet.sort((a, b) => TIER_ORDER[b.severity_tier] - TIER_ORDER[a.severity_tier]);
191	  for (const u of fleet) {
192	    const tr = el("tr", { "data-unit": u.unit_id });
193	
194	    // Unit + Rail Car icon
195	    const unitCell = el("td", {});
196	    unitCell.appendChild(svgRailCar(18));
197	    unitCell.appendChild(document.createTextNode(" " + u.unit_id));
198	    tr.appendChild(unitCell);
199	
200	    tr.appendChild(el("td", { text: u.car }));
201	    tr.appendChild(el("td", { text: String(u.axle) }));
202	    tr.appendChild(el("td", { text: `${(u.speed_mps * 2.237).toFixed(0)} mph` }));
203	
204	    // Temperature with bearing indicator
205	    const tempCell = el("td", {});
206	    const tempStatus = u.peak_temp_f > (u.ambient_temp_f + 170) ? "critical" :
207	                       u.peak_temp_f > (u.ambient_temp_f + 115) ? "warning" : "normal";
208	    tempCell.appendChild(svgBearing(18, tempStatus));
209	    tempCell.appendChild(document.createTextNode(` ${u.peak_temp_f.toFixed(1)}°F`));
210	    tr.appendChild(tempCell);
211	
212	    const badgeCell = el("td", {});
213	    badgeCell.appendChild(el("span", { class: `badge ${tierClass(u.severity_tier)}`, text: u.severity_tier }));
214	    if (u.severity_tier !== "INFORMATIONAL") {
215	      badgeCell.appendChild(el("span", {
216	        class: "corroborated-tag",
217	        text: u.corroborated ? "✓ corroborated" : "⚠ single signal",
218	      }));
219	    }
220	    tr.appendChild(badgeCell);
221	    tr.addEventListener("click", () => showDetail(u.unit_id));
222	    tbody.appendChild(tr);
223	  }
224	}
