226	async function loadAlerts() {
227	  const warrants = await getJSON("/api/alerts");
228	  const list = document.getElementById("alerts-list");
229	  list.innerHTML = "";
230	  if (warrants.length === 0) {
231	    list.appendChild(el("p", { class: "summary", text: "No Ghost Warrants open across the fleet right now." }));
232	    return;
233	  }
234	  for (const w of warrants) {
235	    const div = el("div", { class: "warrant" });
