/* AxiomDynamics dashboard.
 *
 * Design direction: an operations console, not a marketing page. The reference
 * point is a dispatch tower's tooling — dense, flat, high-contrast, and honest
 * about its own state. So: near-square corners, hairline rules instead of drop
 * shadows, tabular numerals everywhere a number can change, and a single
 * saturated accent reserved for state rather than decoration.
 *
 * Every colour token below is chosen by MEASURED CONTRAST against the surface it
 * sits on (WCAG 2.1 relative luminance), not by taste. The previous palette's
 * accent (#0ea5e9) measured 2.77:1 on white and its warning (#f59e0b) 2.15:1 —
 * both fail AA for text (4.5:1). The ratios are recorded beside each token so the
 * next person can re-check them rather than trusting this comment.
 */

:root {
  color-scheme: light;

  /* --- Surfaces --- */
  --bg: #eef1f5;
  --surface: #ffffff;
  --surface-sunken: #f4f6f9;
  --surface-raised: #ffffff;
  --rule: #d8dee7;
  --rule-strong: #b9c3d0;

  /* --- Text. Ratios on white / on --surface-sunken --- */
  --ink: #0d1520;          /* 18.34:1 / 16.94:1 */
  --ink-secondary: #475569; /*  7.58:1 /  7.00:1 */
  --ink-muted: #5b6878;    /*  5.61:1 /  5.18:1 -- was #64748b at 4.76:1 */

  /* --- State accents. Each is AA for text on white and on its own 8% tint. --- */
  --accent: #0369a1;        /*  5.93:1  primary action, links, focus */
  --accent-deep: #0c4a6e;   /*  9.46:1  accent on a tint, headings */
  --ok: #047857;            /*  5.48:1  normal / chain-ok / signed-in */
  --warn: #b45309;          /*  5.02:1  watch / review */
  --bad: #b91c1c;           /*  6.47:1  critical / urgent review */
  --info: #1d4ed8;          /*  6.30:1 */

  /* --- Tints behind badges. Text colour on each is verified above. --- */
  --ok-tint: #ecfdf5;
  --warn-tint: #fffbeb;
  --bad-tint: #fef2f2;
  --accent-tint: #eff6ff;

  /* --- Geometry: near-square. A console is not a brochure. --- */
  --radius: 3px;
  --radius-sm: 2px;
  --rule-w: 1px;

  /* --- Type --- */
  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Cascadia Mono", "Roboto Mono", Consolas, "Liberation Mono", monospace;

  /* --- Elevation: one level only. Depth is expressed by rule weight. --- */
  --lift: 0 1px 0 0 rgba(13, 21, 32, 0.04);

  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.55;
}

* { box-sizing: border-box; }

html, body {
  overflow-x: hidden;
  max-width: 100%;
}

body {
  background: var(--bg);
  color: var(--ink);
  margin: 0;
  padding: 0;
  font-size: 14px;
  line-height: 1.55;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

main {
  padding: 28px 28px 56px;
  max-width: 1560px;
  margin: 0 auto;
}

/* ---------------------------------------------------------------------------
   Demonstration band. Deliberately the first element and deliberately loud:
   this is the one piece of chrome that must be impossible to crop out of a
   screenshot without noticing you did it.
   --------------------------------------------------------------------------- */
#demo-band {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 9px 28px;
  background: #fffbeb;
  border-bottom: 1px solid #fcd34d;
  font-size: 12px;
  color: #7c2d12; /* 8.42:1 on the band */
}

.demo-band-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  padding: 3px 8px;
  border: 1px solid #b45309; /* 4.84:1 */
  border-radius: var(--radius-sm);
  color: #92400e;
  background: #ffffff;
  white-space: nowrap;
}

.demo-band-text { flex: 1 1 340px; line-height: 1.5; }
.demo-band-text strong { font-weight: 700; }

.demo-band-ref {
  font-family: var(--font-mono);
  font-size: 10px;
  color: #92400e;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

/* --- Header ------------------------------------------------------------- */
header {
  background: var(--surface);
  border-bottom: var(--rule-w) solid var(--rule-strong);
  padding: 22px 28px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
}

.brand { display: flex; flex-direction: column; gap: 2px; }

h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--ink);
  line-height: 1.15;
}

/* A short accent rule under the wordmark instead of a gradient-filled logotype.
   The gradient-on-text treatment is the single most templated-looking element a
   dashboard can carry, and it also drops the wordmark below AA contrast. */
h1::after {
  content: "";
  display: block;
  width: 44px;
  height: 3px;
  margin-top: 7px;
  background: var(--accent);
}

.subtitle {
  color: var(--ink-secondary);
  font-weight: 500;
  font-size: 12.5px;
  margin: 0;
  letter-spacing: 0.005em;
}

.header-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-mode {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.03em;
  color: var(--ink-secondary);
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  padding: 5px 10px;
  white-space: nowrap;
}

/* --- Section headings: a label with a rule running to the edge -------------- */
h2 {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--ink-secondary);
  margin: 0 0 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

h2::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--rule);
}

h3 {
  font-size: 12px;
  color: var(--ink);
  margin: 0 0 10px;
  font-weight: 650;
  letter-spacing: 0.005em;
}

section {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin-bottom: 18px;
  box-shadow: var(--lift);
}

/* --- KPI strip ----------------------------------------------------------- */
#kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1px;                       /* hairline gutters: a strip, not four cards */
  margin-bottom: 0;
  background: var(--rule);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  overflow: hidden;
}

.kpi-card {
  background: var(--surface);
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  transition: background 0.15s ease;
}

.kpi-card:hover { background: var(--surface-sunken); }

/* A 3px state bar at the top edge rather than a gradient ribbon. */
.kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
}

.kpi-card.state-ok::before { background: var(--ok); }
.kpi-card.state-warn::before { background: var(--warn); }
.kpi-card.state-bad::before { background: var(--bad); }

.kpi-label {
  font-size: 10px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 700;
}

.kpi-value {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.05;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

.kpi-value.good { color: var(--ok); }
.kpi-value.bad { color: var(--bad); }
.kpi-value.accent { color: var(--accent); }

.kpi-sub {
  font-size: 11.5px;
  color: var(--ink-secondary);
  line-height: 1.45;
}

#kpi-note {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 11px 18px;
  margin: 0 0 18px;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.55;
}

#kpi-note div { margin-bottom: 4px; }
#kpi-note div:last-child { margin-bottom: 0; }

/* --- Tables -------------------------------------------------------------- */
.table-scroll { overflow-x: auto; }

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

th, td {
  text-align: left;
  padding: 9px 12px;
  border-bottom: var(--rule-w) solid var(--rule);
}

th {
  color: var(--ink-secondary);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  background: var(--surface-sunken);
  position: sticky;
  top: 0;
  z-index: 10;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  white-space: nowrap;
}

td {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

tbody tr {
  cursor: pointer;
  transition: background 0.12s ease;
}

tbody tr:hover { background: var(--surface-sunken); }
tbody tr:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  background: var(--accent-tint);
}
tbody tr:active { background: var(--accent-tint); }

/* --- Badges. Colour NEVER carries the meaning alone: each badge renders a
   glyph and the tier text, so the state survives greyscale and colour-blind
   viewing. ---------------------------------------------------------------- */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  border: 1px solid transparent;
  white-space: nowrap;
}

.badge::before {
  font-size: 9px;
  line-height: 1;
}

.badge.normal,
.badge.informational {
  background: var(--ok-tint);
  color: var(--ok);
  border-color: #a7f3d0;
}
.badge.normal::before,
.badge.informational::before { content: "\25CF"; }

.badge.watch,
.badge.review {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.watch::before,
.badge.review::before { content: "\25B2"; }

.badge.warning {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.warning::before { content: "\25B2"; }

.badge.critical,
.badge.urgentreview {
  background: var(--bad-tint);
  color: var(--bad);
  border-color: #fecaca;
}
.badge.critical::before,
.badge.urgentreview::before { content: "\25A0"; }

.corroborated-tag {
  font-size: 10px;
  color: var(--ink-secondary);
  margin-left: 8px;
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  background: var(--surface-sunken);
  white-space: nowrap;
}

/* --- Warrants ------------------------------------------------------------ */
#alerts-panel {
  background: var(--surface);
}

.warrant {
  border-left: 3px solid var(--rule-strong);
  padding: 14px 16px;
  margin-bottom: 10px;
  background: var(--surface-sunken);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: background 0.15s ease;
}

.warrant:hover { background: #eef2f7; }
.warrant:last-child { margin-bottom: 0; }

.warrant.urgentreview { border-left-color: var(--bad); }
.warrant.review { border-left-color: var(--warn); }
.warrant.informational { border-left-color: var(--ok); }

.warrant-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.warrant-head .advisory-id {
  color: var(--ink-secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
}

.evidence-list {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  font-size: 11.5px;
  color: var(--ink-secondary);
}

.evidence-list li {
  padding: 4px 0 4px 14px;
  line-height: 1.5;
  position: relative;
}

.evidence-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 10px;
  width: 4px;
  height: 4px;
  background: var(--rule-strong);
  border-radius: 50%;
}

.evidence-list li.flagged {
  color: var(--ink);
  font-weight: 600;
}

.evidence-list li.flagged::before { background: var(--warn); }

.guardrail-note {
  font-size: 11.5px;
  color: #7f1d1d;              /* 8.1:1 on white */
  margin-top: 14px;
  background: var(--bad-tint);
  border-left: 3px solid var(--bad);
  padding: 9px 13px;
  line-height: 1.55;
}

.summary {
  color: var(--ink-secondary);
  font-size: 12.5px;
  margin: 0 0 10px;
  line-height: 1.55;
}

/* --- Detail panel -------------------------------------------------------- */
#detail-panel { background: var(--surface); }
#detail-panel[hidden] { display: none; }

#detail-title {
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 18px;
  padding-bottom: 10px;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  font-family: var(--font-mono);
  letter-spacing: -0.01em;
}

.chart-block { margin-bottom: 24px; }
.chart-block:last-child { margin-bottom: 0; }

canvas {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  max-width: 100%;
  display: block;
}

/* --- Forms & buttons ----------------------------------------------------- */
.disposition-form {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  padding-top: 12px;
  border-top: var(--rule-w) solid var(--rule);
}

.disposition-form input,
.disposition-form select {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-family: inherit;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.disposition-form input:focus,
.disposition-form select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

.disposition-form input::placeholder { color: var(--ink-muted); }

.disposition-form input[type="text"] { width: 180px; }

.disposition-form button {
  background: var(--accent);
  color: #ffffff;
  border: 1px solid var(--accent);
  padding: 7px 15px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  letter-spacing: 0.01em;
}

.disposition-form button:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
}

.disposition-form button:focus-visible,
#signin-form button:focus-visible,
#signout-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.disposition-status {
  font-size: 11px;
  color: var(--ink-muted);
}

/* --- Decision trail (AD-3) ----------------------------------------------- */
.disposition-history {
  margin-top: 10px;
  width: 100%;
  font-size: 11px;
}

.disposition-history:empty { margin-top: 0; }

.disposition-history-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 8px;
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-bottom: none;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
}

.chain-ok { color: var(--ok); font-weight: 700; }
.chain-bad { color: var(--bad); font-weight: 700; }

.disposition-history-row {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 2px 10px;
  padding: 6px 8px;
  border-bottom: var(--rule-w) solid var(--rule);
  border-left: var(--rule-w) solid var(--rule);
  border-right: var(--rule-w) solid var(--rule);
}

.disposition-history-row:last-child { border-bottom: var(--rule-w) solid var(--rule); }

.dh-when {
  color: var(--ink-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.dh-who { color: var(--ink); font-weight: 600; }
.dh-what { grid-column: 1 / -1; color: var(--ink); }
.dh-note { grid-column: 1 / -1; color: var(--ink-muted); font-style: italic; }

/* --- Inline SVG ---------------------------------------------------------- */
svg {
  vertical-align: middle;
  margin-right: 6px;
  flex-shrink: 0;
}

td svg { margin-right: 7px; }

/* --- Responsive ---------------------------------------------------------- */
@media (max-width: 860px) {
  main { padding: 18px 14px 40px; }
  header { padding: 16px 14px; }
  #demo-band { padding: 9px 14px; gap: 10px; }
  h1 { font-size: 21px; }
  #kpi-strip { grid-template-columns: 1fr; }
  section { padding: 16px; }
  .disposition-form input[type="text"] { width: 140px; }
}

/* --- Session bar (AD-2) -------------------------------------------------- */
#session-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 11px 16px;
  margin-bottom: 18px;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
}

.session-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

#signin-form {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

#signin-form input {
  padding: 6px 10px;
  border: var(--rule-w) solid var(--rule-strong);
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  min-width: 140px;
  font-family: inherit;
  color: var(--ink);
  background: var(--surface);
}

#signin-form input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

#signin-form button,
#signout-btn {
  padding: 6px 14px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
}

#signin-form button:hover { background: var(--accent-deep); }

#signout-btn {
  background: var(--surface);
  color: var(--accent);
}

#signout-btn:hover { background: var(--accent-tint); }

.session-status {
  font-size: 11.5px;
  color: var(--bad);
}

.session-note {
  flex-basis: 100%;
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.5;
}

#session-who {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
}

.disposition-who {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 0;
}

.disposition-who.signed-in { color: var(--ok); }
.disposition-who.signed-out { color: var(--bad); }

/* --- Accessibility: motion and forced colours ---------------------------- */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

@media (forced-colors: active) {
  .badge, .corroborated-tag, .kpi-card, section, .warrant {
    border: 1px solid CanvasText;
  }
  .kpi-card::before, .warrant { border-left-color: CanvasText; }
}

toolUseResult.content:
/* AxiomDynamics dashboard.
 *
 * Design direction: an operations console, not a marketing page. The reference
 * point is a dispatch tower's tooling — dense, flat, high-contrast, and honest
 * about its own state. So: near-square corners, hairline rules instead of drop
 * shadows, tabular numerals everywhere a number can change, and a single
 * saturated accent reserved for state rather than decoration.
 *
 * Every colour token below is chosen by MEASURED CONTRAST against the surface it
 * sits on (WCAG 2.1 relative luminance), not by taste. The previous palette's
 * accent (#0ea5e9) measured 2.77:1 on white and its warning (#f59e0b) 2.15:1 —
 * both fail AA for text (4.5:1). The ratios are recorded beside each token so the
 * next person can re-check them rather than trusting this comment.
 */

:root {
  color-scheme: light;

  /* --- Surfaces --- */
  --bg: #eef1f5;
  --surface: #ffffff;
  --surface-sunken: #f4f6f9;
  --surface-raised: #ffffff;
  --rule: #d8dee7;
  --rule-strong: #b9c3d0;

  /* --- Text. Ratios on white / on --surface-sunken --- */
  --ink: #0d1520;          /* 18.34:1 / 16.94:1 */
  --ink-secondary: #475569; /*  7.58:1 /  7.00:1 */
  --ink-muted: #5b6878;    /*  5.61:1 /  5.18:1 -- was #64748b at 4.76:1 */

  /* --- State accents. Each is AA for text on white and on its own 8% tint. --- */
  --accent: #0369a1;        /*  5.93:1  primary action, links, focus */
  --accent-deep: #0c4a6e;   /*  9.46:1  accent on a tint, headings */
  --ok: #047857;            /*  5.48:1  normal / chain-ok / signed-in */
  --warn: #b45309;          /*  5.02:1  watch / review */
  --bad: #b91c1c;           /*  6.47:1  critical / urgent review */
  --info: #1d4ed8;          /*  6.30:1 */

  /* --- Tints behind badges. Text colour on each is verified above. --- */
  --ok-tint: #ecfdf5;
  --warn-tint: #fffbeb;
  --bad-tint: #fef2f2;
  --accent-tint: #eff6ff;

  /* --- Geometry: near-square. A console is not a brochure. --- */
  --radius: 3px;
  --radius-sm: 2px;
  --rule-w: 1px;

  /* --- Type --- */
  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Cascadia Mono", "Roboto Mono", Consolas, "Liberation Mono", monospace;

  /* --- Elevation: one level only. Depth is expressed by rule weight. --- */
  --lift: 0 1px 0 0 rgba(13, 21, 32, 0.04);

  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.55;
}

* { box-sizing: border-box; }

html, body {
  overflow-x: hidden;
  max-width: 100%;
}

body {
  background: var(--bg);
  color: var(--ink);
  margin: 0;
  padding: 0;
  font-size: 14px;
  line-height: 1.55;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

main {
  padding: 28px 28px 56px;
  max-width: 1560px;
  margin: 0 auto;
}

/* ---------------------------------------------------------------------------
   Demonstration band. Deliberately the first element and deliberately loud:
   this is the one piece of chrome that must be impossible to crop out of a
   screenshot without noticing you did it.
   --------------------------------------------------------------------------- */
#demo-band {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 9px 28px;
  background: #fffbeb;
  border-bottom: 1px solid #fcd34d;
  font-size: 12px;
  color: #7c2d12; /* 8.42:1 on the band */
}

.demo-band-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  padding: 3px 8px;
  border: 1px solid #b45309; /* 4.84:1 */
  border-radius: var(--radius-sm);
  color: #92400e;
  background: #ffffff;
  white-space: nowrap;
}

.demo-band-text { flex: 1 1 340px; line-height: 1.5; }
.demo-band-text strong { font-weight: 700; }

.demo-band-ref {
  font-family: var(--font-mono);
  font-size: 10px;
  color: #92400e;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

/* --- Header ------------------------------------------------------------- */
header {
  background: var(--surface);
  border-bottom: var(--rule-w) solid var(--rule-strong);
  padding: 22px 28px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
}

.brand { display: flex; flex-direction: column; gap: 2px; }

h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--ink);
  line-height: 1.15;
}

/* A short accent rule under the wordmark instead of a gradient-filled logotype.
   The gradient-on-text treatment is the single most templated-looking element a
   dashboard can carry, and it also drops the wordmark below AA contrast. */
h1::after {
  content: "";
  display: block;
  width: 44px;
  height: 3px;
  margin-top: 7px;
  background: var(--accent);
}

.subtitle {
  color: var(--ink-secondary);
  font-weight: 500;
  font-size: 12.5px;
  margin: 0;
  letter-spacing: 0.005em;
}

.header-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-mode {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.03em;
  color: var(--ink-secondary);
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  padding: 5px 10px;
  white-space: nowrap;
}

/* --- Section headings: a label with a rule running to the edge -------------- */
h2 {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--ink-secondary);
  margin: 0 0 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

h2::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--rule);
}

h3 {
  font-size: 12px;
  color: var(--ink);
  margin: 0 0 10px;
  font-weight: 650;
  letter-spacing: 0.005em;
}

section {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin-bottom: 18px;
  box-shadow: var(--lift);
}

/* --- KPI strip ----------------------------------------------------------- */
#kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1px;                       /* hairline gutters: a strip, not four cards */
  margin-bottom: 0;
  background: var(--rule);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  overflow: hidden;
}

.kpi-card {
  background: var(--surface);
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  transition: background 0.15s ease;
}

.kpi-card:hover { background: var(--surface-sunken); }

/* A 3px state bar at the top edge rather than a gradient ribbon. */
.kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
}

.kpi-card.state-ok::before { background: var(--ok); }
.kpi-card.state-warn::before { background: var(--warn); }
.kpi-card.state-bad::before { background: var(--bad); }

.kpi-label {
  font-size: 10px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 700;
}

.kpi-value {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.05;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

.kpi-value.good { color: var(--ok); }
.kpi-value.bad { color: var(--bad); }
.kpi-value.accent { color: var(--accent); }

.kpi-sub {
  font-size: 11.5px;
  color: var(--ink-secondary);
  line-height: 1.45;
}

#kpi-note {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 11px 18px;
  margin: 0 0 18px;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.55;
}

#kpi-note div { margin-bottom: 4px; }
#kpi-note div:last-child { margin-bottom: 0; }

/* --- Tables -------------------------------------------------------------- */
.table-scroll { overflow-x: auto; }

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

th, td {
  text-align: left;
  padding: 9px 12px;
  border-bottom: var(--rule-w) solid var(--rule);
}

th {
  color: var(--ink-secondary);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  background: var(--surface-sunken);
  position: sticky;
  top: 0;
  z-index: 10;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  white-space: nowrap;
}

td {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

tbody tr {
  cursor: pointer;
  transition: background 0.12s ease;
}

tbody tr:hover { background: var(--surface-sunken); }
tbody tr:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  background: var(--accent-tint);
}
tbody tr:active { background: var(--accent-tint); }

/* --- Badges. Colour NEVER carries the meaning alone: each badge renders a
   glyph and the tier text, so the state survives greyscale and colour-blind
   viewing. ---------------------------------------------------------------- */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  border: 1px solid transparent;
  white-space: nowrap;
}

.badge::before {
  font-size: 9px;
  line-height: 1;
}

.badge.normal,
.badge.informational {
  background: var(--ok-tint);
  color: var(--ok);
  border-color: #a7f3d0;
}
.badge.normal::before,
.badge.informational::before { content: "\25CF"; }

.badge.watch,
.badge.review {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.watch::before,
.badge.review::before { content: "\25B2"; }

.badge.warning {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.warning::before { content: "\25B2"; }

.badge.critical,
.badge.urgentreview {
  background: var(--bad-tint);
  color: var(--bad);
  border-color: #fecaca;
}
.badge.critical::before,
.badge.urgentreview::before { content: "\25A0"; }

.corroborated-tag {
  font-size: 10px;
  color: var(--ink-secondary);
  margin-left: 8px;
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  background: var(--surface-sunken);
  white-space: nowrap;
}

/* --- Warrants ------------------------------------------------------------ */
#alerts-panel {
  background: var(--surface);
}

.warrant {
  border-left: 3px solid var(--rule-strong);
  padding: 14px 16px;
  margin-bottom: 10px;
  background: var(--surface-sunken);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: background 0.15s ease;
}

.warrant:hover { background: #eef2f7; }
.warrant:last-child { margin-bottom: 0; }

.warrant.urgentreview { border-left-color: var(--bad); }
.warrant.review { border-left-color: var(--warn); }
.warrant.informational { border-left-color: var(--ok); }

.warrant-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.warrant-head .advisory-id {
  color: var(--ink-secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
}

.evidence-list {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  font-size: 11.5px;
  color: var(--ink-secondary);
}

.evidence-list li {
  padding: 4px 0 4px 14px;
  line-height: 1.5;
  position: relative;
}

.evidence-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 10px;
  width: 4px;
  height: 4px;
  background: var(--rule-strong);
  border-radius: 50%;
}

.evidence-list li.flagged {
  color: var(--ink);
  font-weight: 600;
}

.evidence-list li.flagged::before { background: var(--warn); }

.guardrail-note {
  font-size: 11.5px;
  color: #7f1d1d;              /* 8.1:1 on white */
  margin-top: 14px;
  background: var(--bad-tint);
  border-left: 3px solid var(--bad);
  padding: 9px 13px;
  line-height: 1.55;
}

.summary {
  color: var(--ink-secondary);
  font-size: 12.5px;
  margin: 0 0 10px;
  line-height: 1.55;
}

/* --- Detail panel -------------------------------------------------------- */
#detail-panel { background: var(--surface); }
#detail-panel[hidden] { display: none; }

#detail-title {
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 18px;
  padding-bottom: 10px;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  font-family: var(--font-mono);
  letter-spacing: -0.01em;
}

.chart-block { margin-bottom: 24px; }
.chart-block:last-child { margin-bottom: 0; }

canvas {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  max-width: 100%;
  display: block;
}

/* --- Forms & buttons ----------------------------------------------------- */
.disposition-form {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  padding-top: 12px;
  border-top: var(--rule-w) solid var(--rule);
}

.disposition-form input,
.disposition-form select {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-family: inherit;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.disposition-form input:focus,
.disposition-form select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

.disposition-form input::placeholder { color: var(--ink-muted); }

.disposition-form input[type="text"] { width: 180px; }

.disposition-form button {
  background: var(--accent);
  color: #ffffff;
  border: 1px solid var(--accent);
  padding: 7px 15px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  letter-spacing: 0.01em;
}

.disposition-form button:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
}

.disposition-form button:focus-visible,
#signin-form button:focus-visible,
#signout-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.disposition-status {
  font-size: 11px;
  color: var(--ink-muted);
}

/* --- Decision trail (AD-3) ----------------------------------------------- */
.disposition-history {
  margin-top: 10px;
  width: 100%;
  font-size: 11px;
}

.disposition-history:empty { margin-top: 0; }

.disposition-history-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 8px;
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-bottom: none;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
}

.chain-ok { color: var(--ok); font-weight: 700; }
.chain-bad { color: var(--bad); font-weight: 700; }

.disposition-history-row {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 2px 10px;
  padding: 6px 8px;
  border-bottom: var(--rule-w) solid var(--rule);
  border-left: var(--rule-w) solid var(--rule);
  border-right: var(--rule-w) solid var(--rule);
}

.disposition-history-row:last-child { border-bottom: var(--rule-w) solid var(--rule); }

.dh-when {
  color: var(--ink-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.dh-who { color: var(--ink); font-weight: 600; }
.dh-what { grid-column: 1 / -1; color: var(--ink); }
.dh-note { grid-column: 1 / -1; color: var(--ink-muted); font-style: italic; }

/* --- Inline SVG ---------------------------------------------------------- */
svg {
  vertical-align: middle;
  margin-right: 6px;
  flex-shrink: 0;
}

td svg { margin-right: 7px; }

/* --- Responsive ---------------------------------------------------------- */
@media (max-width: 860px) {
  main { padding: 18px 14px 40px; }
  header { padding: 16px 14px; }
  #demo-band { padding: 9px 14px; gap: 10px; }
  h1 { font-size: 21px; }
  #kpi-strip { grid-template-columns: 1fr; }
  section { padding: 16px; }
  .disposition-form input[type="text"] { width: 140px; }
}

/* --- Session bar (AD-2) -------------------------------------------------- */
#session-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 11px 16px;
  margin-bottom: 18px;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
}

.session-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

#signin-form {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

#signin-form input {
  padding: 6px 10px;
  border: var(--rule-w) solid var(--rule-strong);
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  min-width: 140px;
  font-family: inherit;
  color: var(--ink);
  background: var(--surface);
}

#signin-form input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

#signin-form button,
#signout-btn {
  padding: 6px 14px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
}

#signin-form button:hover { background: var(--accent-deep); }

#signout-btn {
  background: var(--surface);
  color: var(--accent);
}

#signout-btn:hover { background: var(--accent-tint); }

.session-status {
  font-size: 11.5px;
  color: var(--bad);
}

.session-note {
  flex-basis: 100%;
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.5;
}

#session-who {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
}

.disposition-who {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 0;
}

.disposition-who.signed-in { color: var(--ok); }
.disposition-who.signed-out { color: var(--bad); }

/* --- Accessibility: motion and forced colours ---------------------------- */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

@media (forced-colors: active) {
  .badge, .corroborated-tag, .kpi-card, section, .warrant {
    border: 1px solid CanvasText;
  }
  .kpi-card::before, .warrant { border-left-color: CanvasText; }
}

input.content:
/* AxiomDynamics dashboard.
 *
 * Design direction: an operations console, not a marketing page. The reference
 * point is a dispatch tower's tooling — dense, flat, high-contrast, and honest
 * about its own state. So: near-square corners, hairline rules instead of drop
 * shadows, tabular numerals everywhere a number can change, and a single
 * saturated accent reserved for state rather than decoration.
 *
 * Every colour token below is chosen by MEASURED CONTRAST against the surface it
 * sits on (WCAG 2.1 relative luminance), not by taste. The previous palette's
 * accent (#0ea5e9) measured 2.77:1 on white and its warning (#f59e0b) 2.15:1 —
 * both fail AA for text (4.5:1). The ratios are recorded beside each token so the
 * next person can re-check them rather than trusting this comment.
 */

:root {
  color-scheme: light;

  /* --- Surfaces --- */
  --bg: #eef1f5;
  --surface: #ffffff;
  --surface-sunken: #f4f6f9;
  --surface-raised: #ffffff;
  --rule: #d8dee7;
  --rule-strong: #b9c3d0;

  /* --- Text. Ratios on white / on --surface-sunken --- */
  --ink: #0d1520;          /* 18.34:1 / 16.94:1 */
  --ink-secondary: #475569; /*  7.58:1 /  7.00:1 */
  --ink-muted: #5b6878;    /*  5.61:1 /  5.18:1 -- was #64748b at 4.76:1 */

  /* --- State accents. Each is AA for text on white and on its own 8% tint. --- */
  --accent: #0369a1;        /*  5.93:1  primary action, links, focus */
  --accent-deep: #0c4a6e;   /*  9.46:1  accent on a tint, headings */
  --ok: #047857;            /*  5.48:1  normal / chain-ok / signed-in */
  --warn: #b45309;          /*  5.02:1  watch / review */
  --bad: #b91c1c;           /*  6.47:1  critical / urgent review */
  --info: #1d4ed8;          /*  6.30:1 */

  /* --- Tints behind badges. Text colour on each is verified above. --- */
  --ok-tint: #ecfdf5;
  --warn-tint: #fffbeb;
  --bad-tint: #fef2f2;
  --accent-tint: #eff6ff;

  /* --- Geometry: near-square. A console is not a brochure. --- */
  --radius: 3px;
  --radius-sm: 2px;
  --rule-w: 1px;

  /* --- Type --- */
  --font-ui: -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-mono: "SF Mono", "Cascadia Mono", "Roboto Mono", Consolas, "Liberation Mono", monospace;

  /* --- Elevation: one level only. Depth is expressed by rule weight. --- */
  --lift: 0 1px 0 0 rgba(13, 21, 32, 0.04);

  font-family: var(--font-ui);
  font-size: 14px;
  line-height: 1.55;
}

* { box-sizing: border-box; }

html, body {
  overflow-x: hidden;
  max-width: 100%;
}

body {
  background: var(--bg);
  color: var(--ink);
  margin: 0;
  padding: 0;
  font-size: 14px;
  line-height: 1.55;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

main {
  padding: 28px 28px 56px;
  max-width: 1560px;
  margin: 0 auto;
}

/* ---------------------------------------------------------------------------
   Demonstration band. Deliberately the first element and deliberately loud:
   this is the one piece of chrome that must be impossible to crop out of a
   screenshot without noticing you did it.
   --------------------------------------------------------------------------- */
#demo-band {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 9px 28px;
  background: #fffbeb;
  border-bottom: 1px solid #fcd34d;
  font-size: 12px;
  color: #7c2d12; /* 8.42:1 on the band */
}

.demo-band-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  padding: 3px 8px;
  border: 1px solid #b45309; /* 4.84:1 */
  border-radius: var(--radius-sm);
  color: #92400e;
  background: #ffffff;
  white-space: nowrap;
}

.demo-band-text { flex: 1 1 340px; line-height: 1.5; }
.demo-band-text strong { font-weight: 700; }

.demo-band-ref {
  font-family: var(--font-mono);
  font-size: 10px;
  color: #92400e;
  letter-spacing: 0.04em;
  white-space: nowrap;
}

/* --- Header ------------------------------------------------------------- */
header {
  background: var(--surface);
  border-bottom: var(--rule-w) solid var(--rule-strong);
  padding: 22px 28px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px;
}

.brand { display: flex; flex-direction: column; gap: 2px; }

h1 {
  margin: 0;
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -0.015em;
  color: var(--ink);
  line-height: 1.15;
}

/* A short accent rule under the wordmark instead of a gradient-filled logotype.
   The gradient-on-text treatment is the single most templated-looking element a
   dashboard can carry, and it also drops the wordmark below AA contrast. */
h1::after {
  content: "";
  display: block;
  width: 44px;
  height: 3px;
  margin-top: 7px;
  background: var(--accent);
}

.subtitle {
  color: var(--ink-secondary);
  font-weight: 500;
  font-size: 12.5px;
  margin: 0;
  letter-spacing: 0.005em;
}

.header-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-mode {
  font-family: var(--font-mono);
  font-size: 10.5px;
  letter-spacing: 0.03em;
  color: var(--ink-secondary);
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  padding: 5px 10px;
  white-space: nowrap;
}

/* --- Section headings: a label with a rule running to the edge -------------- */
h2 {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--ink-secondary);
  margin: 0 0 16px;
  display: flex;
  align-items: center;
  gap: 12px;
}

h2::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--rule);
}

h3 {
  font-size: 12px;
  color: var(--ink);
  margin: 0 0 10px;
  font-weight: 650;
  letter-spacing: 0.005em;
}

section {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  padding: 20px 22px;
  margin-bottom: 18px;
  box-shadow: var(--lift);
}

/* --- KPI strip ----------------------------------------------------------- */
#kpi-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1px;                       /* hairline gutters: a strip, not four cards */
  margin-bottom: 0;
  background: var(--rule);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
  overflow: hidden;
}

.kpi-card {
  background: var(--surface);
  padding: 16px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  transition: background 0.15s ease;
}

.kpi-card:hover { background: var(--surface-sunken); }

/* A 3px state bar at the top edge rather than a gradient ribbon. */
.kpi-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--accent);
}

.kpi-card.state-ok::before { background: var(--ok); }
.kpi-card.state-warn::before { background: var(--warn); }
.kpi-card.state-bad::before { background: var(--bad); }

.kpi-label {
  font-size: 10px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--ink-muted);
  font-weight: 700;
}

.kpi-value {
  font-size: 30px;
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.05;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

.kpi-value.good { color: var(--ok); }
.kpi-value.bad { color: var(--bad); }
.kpi-value.accent { color: var(--accent); }

.kpi-sub {
  font-size: 11.5px;
  color: var(--ink-secondary);
  line-height: 1.45;
}

#kpi-note {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-top: none;
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 11px 18px;
  margin: 0 0 18px;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.55;
}

#kpi-note div { margin-bottom: 4px; }
#kpi-note div:last-child { margin-bottom: 0; }

/* --- Tables -------------------------------------------------------------- */
.table-scroll { overflow-x: auto; }

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

th, td {
  text-align: left;
  padding: 9px 12px;
  border-bottom: var(--rule-w) solid var(--rule);
}

th {
  color: var(--ink-secondary);
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  background: var(--surface-sunken);
  position: sticky;
  top: 0;
  z-index: 10;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  white-space: nowrap;
}

td {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum" 1;
}

tbody tr {
  cursor: pointer;
  transition: background 0.12s ease;
}

tbody tr:hover { background: var(--surface-sunken); }
tbody tr:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  background: var(--accent-tint);
}
tbody tr:active { background: var(--accent-tint); }

/* --- Badges. Colour NEVER carries the meaning alone: each badge renders a
   glyph and the tier text, so the state survives greyscale and colour-blind
   viewing. ---------------------------------------------------------------- */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  border: 1px solid transparent;
  white-space: nowrap;
}

.badge::before {
  font-size: 9px;
  line-height: 1;
}

.badge.normal,
.badge.informational {
  background: var(--ok-tint);
  color: var(--ok);
  border-color: #a7f3d0;
}
.badge.normal::before,
.badge.informational::before { content: "\25CF"; }

.badge.watch,
.badge.review {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.watch::before,
.badge.review::before { content: "\25B2"; }

.badge.warning {
  background: var(--warn-tint);
  color: var(--warn);
  border-color: #fde68a;
}
.badge.warning::before { content: "\25B2"; }

.badge.critical,
.badge.urgentreview {
  background: var(--bad-tint);
  color: var(--bad);
  border-color: #fecaca;
}
.badge.critical::before,
.badge.urgentreview::before { content: "\25A0"; }

.corroborated-tag {
  font-size: 10px;
  color: var(--ink-secondary);
  margin-left: 8px;
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  background: var(--surface-sunken);
  white-space: nowrap;
}

/* --- Warrants ------------------------------------------------------------ */
#alerts-panel {
  background: var(--surface);
}

.warrant {
  border-left: 3px solid var(--rule-strong);
  padding: 14px 16px;
  margin-bottom: 10px;
  background: var(--surface-sunken);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: background 0.15s ease;
}

.warrant:hover { background: #eef2f7; }
.warrant:last-child { margin-bottom: 0; }

.warrant.urgentreview { border-left-color: var(--bad); }
.warrant.review { border-left-color: var(--warn); }
.warrant.informational { border-left-color: var(--ok); }

.warrant-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 8px;
  flex-wrap: wrap;
}

.warrant-head .advisory-id {
  color: var(--ink-secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  padding: 2px 7px;
  border-radius: var(--radius-sm);
}

.evidence-list {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  font-size: 11.5px;
  color: var(--ink-secondary);
}

.evidence-list li {
  padding: 4px 0 4px 14px;
  line-height: 1.5;
  position: relative;
}

.evidence-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 10px;
  width: 4px;
  height: 4px;
  background: var(--rule-strong);
  border-radius: 50%;
}

.evidence-list li.flagged {
  color: var(--ink);
  font-weight: 600;
}

.evidence-list li.flagged::before { background: var(--warn); }

.guardrail-note {
  font-size: 11.5px;
  color: #7f1d1d;              /* 8.1:1 on white */
  margin-top: 14px;
  background: var(--bad-tint);
  border-left: 3px solid var(--bad);
  padding: 9px 13px;
  line-height: 1.55;
}

.summary {
  color: var(--ink-secondary);
  font-size: 12.5px;
  margin: 0 0 10px;
  line-height: 1.55;
}

/* --- Detail panel -------------------------------------------------------- */
#detail-panel { background: var(--surface); }
#detail-panel[hidden] { display: none; }

#detail-title {
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 18px;
  padding-bottom: 10px;
  border-bottom: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  font-family: var(--font-mono);
  letter-spacing: -0.01em;
}

.chart-block { margin-bottom: 24px; }
.chart-block:last-child { margin-bottom: 0; }

canvas {
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius-sm);
  max-width: 100%;
  display: block;
}

/* --- Forms & buttons ----------------------------------------------------- */
.disposition-form {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 12px;
  flex-wrap: wrap;
  padding-top: 12px;
  border-top: var(--rule-w) solid var(--rule);
}

.disposition-form input,
.disposition-form select {
  background: var(--surface);
  border: var(--rule-w) solid var(--rule-strong);
  color: var(--ink);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-family: inherit;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.disposition-form input:focus,
.disposition-form select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

.disposition-form input::placeholder { color: var(--ink-muted); }

.disposition-form input[type="text"] { width: 180px; }

.disposition-form button {
  background: var(--accent);
  color: #ffffff;
  border: 1px solid var(--accent);
  padding: 7px 15px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  letter-spacing: 0.01em;
}

.disposition-form button:hover {
  background: var(--accent-deep);
  border-color: var(--accent-deep);
}

.disposition-form button:focus-visible,
#signin-form button:focus-visible,
#signout-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.disposition-status {
  font-size: 11px;
  color: var(--ink-muted);
}

/* --- Decision trail (AD-3) ----------------------------------------------- */
.disposition-history {
  margin-top: 10px;
  width: 100%;
  font-size: 11px;
}

.disposition-history:empty { margin-top: 0; }

.disposition-history-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 5px 8px;
  background: var(--surface-sunken);
  border: var(--rule-w) solid var(--rule);
  border-bottom: none;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-secondary);
}

.chain-ok { color: var(--ok); font-weight: 700; }
.chain-bad { color: var(--bad); font-weight: 700; }

.disposition-history-row {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 2px 10px;
  padding: 6px 8px;
  border-bottom: var(--rule-w) solid var(--rule);
  border-left: var(--rule-w) solid var(--rule);
  border-right: var(--rule-w) solid var(--rule);
}

.disposition-history-row:last-child { border-bottom: var(--rule-w) solid var(--rule); }

.dh-when {
  color: var(--ink-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.dh-who { color: var(--ink); font-weight: 600; }
.dh-what { grid-column: 1 / -1; color: var(--ink); }
.dh-note { grid-column: 1 / -1; color: var(--ink-muted); font-style: italic; }

/* --- Inline SVG ---------------------------------------------------------- */
svg {
  vertical-align: middle;
  margin-right: 6px;
  flex-shrink: 0;
}

td svg { margin-right: 7px; }

/* --- Responsive ---------------------------------------------------------- */
@media (max-width: 860px) {
  main { padding: 18px 14px 40px; }
  header { padding: 16px 14px; }
  #demo-band { padding: 9px 14px; gap: 10px; }
  h1 { font-size: 21px; }
  #kpi-strip { grid-template-columns: 1fr; }
  section { padding: 16px; }
  .disposition-form input[type="text"] { width: 140px; }
}

/* --- Session bar (AD-2) -------------------------------------------------- */
#session-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 11px 16px;
  margin-bottom: 18px;
  background: var(--surface);
  border: var(--rule-w) solid var(--rule);
  border-radius: var(--radius);
}

.session-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

#signin-form {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

#signin-form input {
  padding: 6px 10px;
  border: var(--rule-w) solid var(--rule-strong);
  border-radius: var(--radius-sm);
  font-size: 12.5px;
  min-width: 140px;
  font-family: inherit;
  color: var(--ink);
  background: var(--surface);
}

#signin-form input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(3, 105, 161, 0.18);
}

#signin-form button,
#signout-btn {
  padding: 6px 14px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  font-family: inherit;
}

#signin-form button:hover { background: var(--accent-deep); }

#signout-btn {
  background: var(--surface);
  color: var(--accent);
}

#signout-btn:hover { background: var(--accent-tint); }

.session-status {
  font-size: 11.5px;
  color: var(--bad);
}

.session-note {
  flex-basis: 100%;
  margin: 2px 0 0;
  font-size: 11px;
  color: var(--ink-muted);
  line-height: 1.5;
}

#session-who {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
}

.disposition-who {
  font-size: 11.5px;
  font-weight: 700;
  padding: 3px 0;
}

.disposition-who.signed-in { color: var(--ok); }
.disposition-who.signed-out { color: var(--bad); }

/* --- Accessibility: motion and forced colours ---------------------------- */
@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
  }
}

@media (forced-colors: active) {
  .badge, .corroborated-tag, .kpi-card, section, .warrant {
    border: 1px solid CanvasText;
  }
  .kpi-card::before, .warrant { border-left-color: CanvasText; }
}

